package com.game_manager.gm.workflow; import com.game_manager.gm.workflow.dto.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/workflows") public class WorkflowController {private final WorkflowService service;public WorkflowController(WorkflowService s){service=s;}
 @GetMapping("/definitions")public List<WorkflowDefinitionResponse> definitions(){return service.definitions();}@PostMapping("/definitions")public ResponseEntity<WorkflowDefinitionResponse> publish(@Valid@RequestBody WorkflowDefinitionRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.publish(r));}
 @PostMapping public ResponseEntity<WorkflowSummaryResponse> create(@Valid@RequestBody CreateWorkflowRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@GetMapping("/inbox")public List<WorkflowSummaryResponse> inbox(){return service.inbox();}@GetMapping("/mine")public List<WorkflowSummaryResponse> mine(){return service.mine();}@GetMapping("/{id}")public WorkflowDetailResponse detail(@PathVariable UUID id){return service.detail(id);}@PostMapping("/{id}/actions")public WorkflowDetailResponse act(@PathVariable UUID id,@Valid@RequestBody WorkflowActionRequest r){return service.act(id,r);}@PostMapping("/{id}/comments")public WorkflowDetailResponse comment(@PathVariable UUID id,@Valid@RequestBody WorkflowCommentRequest r){return service.comment(id,r);}@PostMapping("/{id}/documents")public WorkflowDetailResponse link(@PathVariable UUID id,@Valid@RequestBody WorkflowLinkRequest r){return service.link(id,r);}}
